    @IsTest
    static void verifiedResponseLeavesAccountUntouched() {
        // Quotes, a backslash, and markup must survive the JSON body exactly.
        Account acct = accountWith('12 "Main" \\ St', 'A & B <City>', '01310-100', 'BR');
        AddressVerificationService.Result result = verifyOk(
