        public fflib_ApexMocks mocks;
        public fflib_ISObjectUnitOfWork uow;
        public IOpportunitiesSelector selector;
        public IOpportunities domain;
        public List<Opportunity> opportunities;
        public Set<Id> opportunityIds;

        public Fixture() {
            mocks = new fflib_ApexMocks();
            uow = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
            selector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
            domain = (IOpportunities) mocks.mock(IOpportunities.class);

            opportunities = new List<Opportunity>{
                newOpportunity('Alpha', 1000),
                newOpportunity('Beta', 2500.5)
            };
            opportunityIds = new Map<Id, Opportunity>(opportunities).keySet();

            mocks.startStubbing();
            mocks.when(selector.sObjectType()).thenReturn(Opportunity.SObjectType);
            mocks.when(domain.sObjectType()).thenReturn(Opportunity.SObjectType);
            mocks.when(selector.selectById(opportunityIds)).thenReturn(opportunities);
            mocks.stopStubbing();

            Application.UnitOfWork.setMock(uow);
            Application.Selector.setMock(selector);
