public with sharing class Opportunities extends fflib_SObjectDomain
{
    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String MSG_AMOUNT_NEGATIVE = 'Amount cannot be negative.';
    private static final String MSG_AMOUNT_LOCKED = 'Amount cannot change on a won opportunity.';

    public Opportunities(List<Opportunity> sObjectList)
    {
        super(sObjectList);
    }

    // fflib calls onValidate from after insert/update. Field addError in that phase
    // does not fail the row (including partial DML), so run the hooks beforehand.
    public override void onBeforeInsert()
    {
        onValidate();
    }

    public override void onBeforeUpdate(Map<Id, SObject> existingRecords)
    {
        onValidate(existingRecords);
    }

    public override void onValidate()
    {
        if (isAfterTriggerPhase())
        {
            return;
        }

        for (Opportunity opp : (List<Opportunity>) Records)
        {
            validateAmountNotNegative(opp);
        }
    }

    public override void onValidate(Map<Id, SObject> existingRecords)
    {
        if (isAfterTriggerPhase())
        {
            return;
        }

        for (Opportunity opp : (List<Opportunity>) Records)
        {
            validateAmountNotNegative(opp);
            validateWonAmountUnchanged(opp, existingRecords);
        }
    }

    private Boolean isAfterTriggerPhase()
    {
        return Trigger.isExecuting && Trigger.isAfter;
    }

    private void validateAmountNotNegative(Opportunity opp)
    {
        if (opp.Amount != null && opp.Amount < 0)
        {
            error(MSG_AMOUNT_NEGATIVE, opp, Opportunity.Amount);
        }
    }

    private void validateWonAmountUnchanged(Opportunity opp, Map<Id, SObject> existingRecords)
    {
        if (existingRecords == null || opp.Id == null)
        {
            return;
        }

        Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
        // Only when the opportunity was already Closed Won. Winning and changing
        // Amount in the same update is allowed.
        if (oldOpp != null
            && oldOpp.StageName == STAGE_CLOSED_WON
            && opp.Amount != oldOpp.Amount)
        {
            error(MSG_AMOUNT_LOCKED, opp, Opportunity.Amount);
        }
    }

