/**
 * Records a gift that has already been received as a Closed Won NPSP donation.
 * Contact-role and payment automation are suppressed on the gift, then the
 * household credits and the single paid payment are written explicitly so the
 * result does not depend on org soft-credit or payment settings.
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    /**
     * Records a Closed Won donation of {@code amount} from the contact, closed on
     * {@code giftDate}, and returns the Opportunity Id.
     *
     * @throws IllegalArgumentException if the contact does not exist, the contact has
     *         no household account, {@code amount} is null, zero, or negative, or
     *         {@code giftDate} is null.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }
        if (contactId == null || contactId.getSObjectType() != Contact.SObjectType) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        Contact donor = donors[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact does not belong to a household account.');
        }

        String giftName = buildGiftName(donor, giftDate);
        Opportunity gift = new Opportunity(
            Name = giftName,
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            Amount = amount,
            CloseDate = giftDate,
            StageName = STAGE_CLOSED_WON,
            npe01__Do_Not_Automatically_Create_Payment__c = true,
            npsp__DisableContactRoleAutomation__c = true
        );

        // Opportunity naming reads the cached handler list the first time a trigger
        // runs in this transaction. Deactivate it before that cache is built, and
        // reapply the required name after DML in case it was already built.
        NamingSuspension naming = new NamingSuspension();
        naming.suspend();
        try {
            insert gift;
            new HouseholdCrediting().credit(
                gift.Id,
                donor.Id,
                donor.AccountId,
                amount,
                giftDate,
                giftName
            );
            return gift.Id;
        } finally {
            naming.restore();
        }
    }

    private static String buildGiftName(Contact donor, Date giftDate) {
        String who = String.isBlank(donor.FirstName)
            ? donor.LastName
            : donor.FirstName + ' ' + donor.LastName;
        return who + ' Donation ' + String.valueOf(giftDate);
    }

    /**
     * Deactivates NPSP opportunity-naming handlers on the transaction cache.
     * TDTM_Config_API has no setter; the cached list is the live list the trigger
     * framework reads, so clearing Active__c in place is enough.
     */
    private class NamingSuspension {
        private List<npsp__Trigger_Handler__c> handlers;
        private List<Boolean> priorActive = new List<Boolean>();

        public void suspend() {
            handlers = npsp.TDTM_Config_API.getCachedRecords();
            if (handlers == null) {
                return;
            }
            for (npsp__Trigger_Handler__c handler : handlers) {
                priorActive.add(handler.npsp__Active__c);
                String className = handler.npsp__Class__c == null
                    ? ''
                    : handler.npsp__Class__c.toLowerCase();
                if (className.contains('opportunitynaming') && handler.npsp__Active__c == true) {
                    handler.npsp__Active__c = false;
                }
            }
        }

        public void restore() {
            if (handlers == null) {
                return;
            }
            Integer limitSize = Math.min(handlers.size(), priorActive.size());
            for (Integer i = 0; i < limitSize; i++) {
                handlers[i].npsp__Active__c = priorActive[i];
            }
        }
    }

    /**
     * Credits every household member, including members the running user cannot see.
     * The donor was already loaded with sharing, so an invisible contact is rejected.
     */
    private without sharing class HouseholdCrediting {

        public void credit(
            Id opportunityId,
            Id donorId,
            Id accountId,
            Decimal amount,
            Date giftDate,
            String giftName
        ) {
            Set<Id> memberIds = householdContactIds(accountId);
            memberIds.add(donorId);

            putRoles(opportunityId, donorId, memberIds);
            putPayment(opportunityId, amount, giftDate);
            // A child write can update the opportunity and make NPSP add another child.
            if (repairHeader(opportunityId, donorId, accountId, amount, giftDate)) {
                putRoles(opportunityId, donorId, memberIds);
                putPayment(opportunityId, amount, giftDate);
            }
            forceName(opportunityId, giftName);
        }

        private Set<Id> householdContactIds(Id accountId) {
            Set<Id> contactIds = new Set<Id>();
            for (Contact member : [
                SELECT Id
                FROM Contact
                WHERE AccountId = :accountId
            ]) {
                contactIds.add(member.Id);
            }
            return contactIds;
        }

        private void putRoles(Id opportunityId, Id donorId, Set<Id> memberIds) {
            Map<Id, OpportunityContactRole> keeperByContact = collapseRoles(opportunityId, memberIds);

            List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
            List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
            for (Id memberId : memberIds) {
                Boolean isDonor = memberId == donorId;
                String desiredRole = isDonor ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER;
                OpportunityContactRole keeper = keeperByContact.get(memberId);
                if (keeper == null) {
                    toInsert.add(new OpportunityContactRole(
                        OpportunityId = opportunityId,
                        ContactId = memberId,
                        Role = desiredRole,
                        IsPrimary = false
                    ));
                    continue;
                }
                if (keeper.Role != desiredRole || (keeper.IsPrimary && !isDonor)) {
                    keeper.Role = desiredRole;
                    if (!isDonor) {
                        keeper.IsPrimary = false;
                    }
                    toUpdate.add(keeper);
                }
            }
            if (!toUpdate.isEmpty()) {
                update toUpdate;
            }
            if (!toInsert.isEmpty()) {
                insert toInsert;
            }

            // The insert can cause NPSP to add a second role. Collapse again, clear
            // every other primary, then mark the donor. Two primaries are never
            // written in the same DML.
            keeperByContact = collapseRoles(opportunityId, memberIds);
            List<OpportunityContactRole> demotions = new List<OpportunityContactRole>();
            OpportunityContactRole donorRole = keeperByContact.get(donorId);
            for (OpportunityContactRole role : keeperByContact.values()) {
                if (role.ContactId == donorId) {
                    continue;
                }
                if (role.IsPrimary || role.Role != ROLE_HOUSEHOLD_MEMBER) {
                    role.Role = ROLE_HOUSEHOLD_MEMBER;
                    role.IsPrimary = false;
                    demotions.add(role);
                }
            }
            if (!demotions.isEmpty()) {
                update demotions;
            }
            if (donorRole == null) {
                insert new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = donorId,
                    Role = ROLE_DONOR,
                    IsPrimary = true
                );
            } else if (donorRole.Role != ROLE_DONOR || donorRole.IsPrimary != true) {
                update new OpportunityContactRole(
                    Id = donorRole.Id,
                    Role = ROLE_DONOR,
                    IsPrimary = true
                );
            }
        }

        private Map<Id, OpportunityContactRole> collapseRoles(Id opportunityId, Set<Id> memberIds) {
            List<OpportunityContactRole> existing = [
                SELECT Id, ContactId, Role, IsPrimary
                FROM OpportunityContactRole
                WHERE OpportunityId = :opportunityId
                ORDER BY CreatedDate ASC, Id ASC
            ];

            Map<Id, OpportunityContactRole> keeperByContact = new Map<Id, OpportunityContactRole>();
            List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
            for (OpportunityContactRole role : existing) {
                if (role.ContactId == null
                    || !memberIds.contains(role.ContactId)
                    || keeperByContact.containsKey(role.ContactId)) {
                    toDelete.add(role);
                } else {
                    keeperByContact.put(role.ContactId, role);
                }
            }
            if (!toDelete.isEmpty()) {
                delete toDelete;
            }
            return keeperByContact;
        }

        private void putPayment(Id opportunityId, Decimal amount, Date giftDate) {
            List<npe01__OppPayment__c> payments = [
                SELECT Id,
                       npe01__Payment_Amount__c,
                       npe01__Payment_Date__c,
                       npe01__Scheduled_Date__c,
                       npe01__Paid__c
                FROM npe01__OppPayment__c
                WHERE npe01__Opportunity__c = :opportunityId
                ORDER BY CreatedDate ASC, Id ASC
            ];

            List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
            for (Integer i = 1; i < payments.size(); i++) {
                extras.add(payments[i]);
            }
            if (!extras.isEmpty()) {
                delete extras;
            }

            if (payments.isEmpty()) {
                insert newPayment(opportunityId, null, amount, giftDate);
            } else if (!isPaymentCorrect(payments[0], amount, giftDate)) {
                update newPayment(opportunityId, payments[0].Id, amount, giftDate);
            }

            // Rewriting the keeper can cause NPSP to insert the outstanding balance
            // as another payment. Remove that extra without rewriting the keeper.
            deleteExtraPayments(opportunityId);
        }

        private Boolean isPaymentCorrect(npe01__OppPayment__c payment, Decimal amount, Date giftDate) {
            return payment.npe01__Paid__c == true
                && payment.npe01__Payment_Amount__c == amount
                && payment.npe01__Payment_Date__c == giftDate
                && payment.npe01__Scheduled_Date__c == giftDate;
        }

        private npe01__OppPayment__c newPayment(
            Id opportunityId,
            Id paymentId,
            Decimal amount,
            Date giftDate
        ) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c(
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            if (paymentId == null) {
                payment.npe01__Opportunity__c = opportunityId;
            } else {
                payment.Id = paymentId;
            }
            return payment;
        }

        private void deleteExtraPayments(Id opportunityId) {
            List<npe01__OppPayment__c> payments = [
                SELECT Id
                FROM npe01__OppPayment__c
                WHERE npe01__Opportunity__c = :opportunityId
                ORDER BY CreatedDate ASC, Id ASC
            ];
            if (payments.size() <= 1) {
                return;
            }
            List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
            for (Integer i = 1; i < payments.size(); i++) {
                extras.add(payments[i]);
            }
            delete extras;
        }

        /**
         * @return true when the header had to be rewritten. Callers then resynchronize
         *         children, because an amount or stage change can make NPSP add one.
         *         The name is applied separately so a naming rule cannot discard it
         *         while other fields are changing.
         */
        private Boolean repairHeader(
            Id opportunityId,
            Id donorId,
            Id accountId,
            Decimal amount,
            Date giftDate
        ) {
            Opportunity current = [
                SELECT Amount, CloseDate, StageName, AccountId, npsp__Primary_Contact__c,
                       npe01__Do_Not_Automatically_Create_Payment__c,
                       npsp__DisableContactRoleAutomation__c
                FROM Opportunity
                WHERE Id = :opportunityId
                LIMIT 1
            ];

            Opportunity patch = new Opportunity(Id = opportunityId);
            Boolean changed = false;
            if (current.Amount != amount) {
                patch.Amount = amount;
                changed = true;
            }
            if (current.CloseDate != giftDate) {
                patch.CloseDate = giftDate;
                changed = true;
            }
            if (current.StageName != STAGE_CLOSED_WON) {
                patch.StageName = STAGE_CLOSED_WON;
                changed = true;
            }
            if (current.AccountId != accountId) {
                patch.AccountId = accountId;
                changed = true;
            }
            if (current.npsp__Primary_Contact__c != donorId) {
                patch.npsp__Primary_Contact__c = donorId;
                changed = true;
            }
            if (current.npe01__Do_Not_Automatically_Create_Payment__c != true) {
                patch.npe01__Do_Not_Automatically_Create_Payment__c = true;
                changed = true;
            }
            if (current.npsp__DisableContactRoleAutomation__c != true) {
                patch.npsp__DisableContactRoleAutomation__c = true;
                changed = true;
            }
            if (changed) {
                update patch;
            }
            return changed;
        }

        private void forceName(Id opportunityId, String giftName) {
            Opportunity current = [
                SELECT Name
                FROM Opportunity
                WHERE Id = :opportunityId
                LIMIT 1
            ];
            if (current.Name == giftName) {
                return;
            }
            update new Opportunity(
                Id = opportunityId,
                Name = giftName,
                npe01__Do_Not_Automatically_Create_Payment__c = true,
                npsp__DisableContactRoleAutomation__c = true
            );
        }
    }
